am}+=&quot;/bin/sh -c '/bin/cp %E{TMP_MOUNT_DIR}/.first-mount.sh %E{TMP_SCRIPT} || exit 0'&quot;\nRUN{program}+=&quot;/bin/umount %E{TMP_MOUNT_DIR}&quot;\nRUN{program",
