import sys, json, html, re
data = sys.stdin.read()
start = data.find('{')
end = data.rfind('}') + 1
j = json.loads(html.unescape(data[start:end]))
print('=== Full JSON keys with values (non-long fields) ===')
def print_flat(d, prefix=''):
    if isinstance(d, dict):
        for k, v in d.items():
            print_flat(v, prefix + k + '.')
    elif isinstance(d, list):
        for i, v in enumerate(d):
            print_flat(v, prefix + str(i) + '.')
    else:
        val = str(d)
        if len(val) < 200:
            print(f'{prefix[:-1]}: {val}')
            # Look for UUID-like patterns
            uuids = re.findall(r'[0-9a-f]{8}-?[0-9a-f]{4}-?[0-9a-f]{4}-?[0-9a-f]{4}-?[0-9a-f]{12}', val, re.I)
            if uuids: print(f'  >>> UUID FOUND: {uuids}')
print_flat(j)
" 2>&1
